package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.*;import com.makemytrip.makemytrip.repositories.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.time.Duration;import java.time.LocalDateTime;import java.time.OffsetDateTime;import java.util.Objects;
/** Isolated mock provider; replace this implementation when integrating a live aviation provider. */
@Service public class FlightStatusService {
 private final FlightRepository flights;private final FlightStatusRepository statuses;private final FlightNotificationService notifications;
 @Value("${flight-status.simulation-enabled:true}") private boolean simulationEnabled;
 @Value("${flight-status.simulation-interval-seconds:60}") private long simulationIntervalSeconds;
 public FlightStatusService(FlightRepository flights,FlightStatusRepository statuses){this(flights,statuses,null);}
 @Autowired public FlightStatusService(FlightRepository flights,FlightStatusRepository statuses,FlightNotificationService notifications){this.flights=flights;this.statuses=statuses;this.notifications=notifications;}
 public FlightStatus get(String id){Flight f=flights.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Flight not found"));FlightStatus s=statuses.findByFlightId(id).orElseGet(()->{FlightStatus created=new FlightStatus();created.setFlightId(id);created.setFlightNumber(f.getFlightNumber());created.setAirline(f.getAirline());created.setOrigin(f.getFrom());created.setDestination(f.getTo());created.setScheduledDeparture(f.getDepartureTime());created.setEstimatedDeparture(f.getDepartureTime());created.setScheduledArrival(f.getArrivalTime());created.setEstimatedArrival(f.getArrivalTime());created.setTerminal(f.getTerminal());created.setGate(f.getGate());created.setStatus(FlightStatus.State.ON_TIME);created.setSimulated(true);created.setLastUpdated(Instant.now());return statuses.save(created);});return simulate(s);}
 public FlightStatus byNumber(String number){return flights.findAll().stream().filter(f->number.equalsIgnoreCase(f.getFlightNumber())).findFirst().map(f->get(f.getId())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Flight not found"));}
 public FlightStatus update(String flightId,FlightStatus input){Flight f=flights.findById(flightId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Flight not found"));FlightStatus s=statuses.findByFlightId(flightId).orElseGet(FlightStatus::new);FlightStatus before=s.getFlightId()==null?null:snapshot(s);s.setFlightId(flightId);s.setFlightNumber(input.getFlightNumber()==null?f.getFlightNumber():input.getFlightNumber());s.setAirline(input.getAirline()==null?f.getAirline():input.getAirline());s.setOrigin(input.getOrigin()==null?f.getFrom():input.getOrigin());s.setDestination(input.getDestination()==null?f.getTo():input.getDestination());s.setScheduledDeparture(input.getScheduledDeparture()==null?f.getDepartureTime():input.getScheduledDeparture());s.setEstimatedDeparture(input.getEstimatedDeparture()==null?(s.getEstimatedDeparture()==null?s.getScheduledDeparture():s.getEstimatedDeparture()):input.getEstimatedDeparture());s.setScheduledArrival(input.getScheduledArrival()==null?f.getArrivalTime():input.getScheduledArrival());s.setEstimatedArrival(input.getEstimatedArrival()==null?(s.getEstimatedArrival()==null?s.getScheduledArrival():s.getEstimatedArrival()):input.getEstimatedArrival());s.setTerminal(input.getTerminal()==null?f.getTerminal():input.getTerminal());s.setGate(input.getGate()==null?f.getGate():input.getGate());s.setStatus(input.getStatus()==null?FlightStatus.State.ON_TIME:input.getStatus());s.setDelayMinutes(Math.max(0,input.getDelayMinutes()));s.setDelayReason(input.getDelayReason());if(s.getStatus()==FlightStatus.State.DELAYED&&s.getDelayMinutes()==0){s.setDelayMinutes(15);if(s.getDelayReason()==null)s.setDelayReason("MOCK_OPERATIONAL_DELAY");}s.setSimulated(false);s.setLastUpdated(Instant.now());FlightStatus saved=statuses.save(s);publish(before,saved);return saved;}
 private FlightStatus simulate(FlightStatus s){if(s.getLastUpdated()==null){s.setLastUpdated(Instant.now());return statuses.save(s);}if(!simulationEnabled||!s.isSimulated()||s.getStatus()==FlightStatus.State.CANCELLED||s.getStatus()==FlightStatus.State.LANDED||Duration.between(s.getLastUpdated(),Instant.now()).getSeconds()<simulationIntervalSeconds)return s;FlightStatus before=snapshot(s);FlightStatus.State next=switch(s.getStatus()){case ON_TIME->FlightStatus.State.BOARDING;case BOARDING->Math.floorMod(Objects.hashCode(s.getFlightId()),3)==0?FlightStatus.State.DELAYED:FlightStatus.State.DEPARTED;case DELAYED->FlightStatus.State.DEPARTED;case DEPARTED->FlightStatus.State.IN_AIR;case IN_AIR->FlightStatus.State.LANDED;default->s.getStatus();};s.setStatus(next);if(next==FlightStatus.State.DELAYED){s.setDelayMinutes(15);s.setDelayReason("MOCK_OPERATIONAL_DELAY");s.setEstimatedDeparture(shiftDeparture(s.getEstimatedDeparture(),15));s.setEstimatedArrival(shiftDeparture(s.getEstimatedArrival(),15));}s.setLastUpdated(Instant.now());FlightStatus saved=statuses.save(s);publish(before,saved);return saved;}
 private String shiftDeparture(String value,int minutes){if(value==null)return null;try{return LocalDateTime.parse(value).plusMinutes(minutes).toString();}catch(Exception ignored){}try{return OffsetDateTime.parse(value).plusMinutes(minutes).toString();}catch(Exception ignored){return value;}}
 private void publish(FlightStatus before,FlightStatus after){if(notifications!=null)notifications.statusChanged(before,after);}
 private FlightStatus snapshot(FlightStatus s){FlightStatus c=new FlightStatus();c.setFlightId(s.getFlightId());c.setFlightNumber(s.getFlightNumber());c.setAirline(s.getAirline());c.setOrigin(s.getOrigin());c.setDestination(s.getDestination());c.setScheduledDeparture(s.getScheduledDeparture());c.setEstimatedDeparture(s.getEstimatedDeparture());c.setScheduledArrival(s.getScheduledArrival());c.setEstimatedArrival(s.getEstimatedArrival());c.setTerminal(s.getTerminal());c.setGate(s.getGate());c.setStatus(s.getStatus());c.setDelayMinutes(s.getDelayMinutes());c.setDelayReason(s.getDelayReason());c.setLastUpdated(s.getLastUpdated());c.setSimulated(s.isSimulated());return c;}
}
